"""
author:wjw
分析：将0换为-1，求连续区间和为0的子数组，返回长度。哈希表存放前缀和为sum的最小index。
"""


import time


class Solution:
    def findMaxLength(self, nums):
        n = len(nums)
        sum = 0
        d = {0:-1}
        ans = 0

        for i in range(n):
            if nums[i] == 0:
                sum += -1
            if nums[i] == 1:
                sum += 1

            if sum in d.keys():
                ans = max(ans, i - d[sum])
                d[sum] = min(d[sum], i)
            else:
                d[sum] = i
        return ans


